
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_r2scan_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_r2scan", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.656294329086108e-02, -2.651934647710527e-02, -2.645502124155797e-02, -2.635910787477014e-02, -2.621404479941617e-02, -2.599066817264337e-02, -2.564034165666716e-02, -2.509100821090468e-02, -2.433919114004999e-02, -2.494232119979525e-02, -3.073294922485397e-02, -4.855976637200535e-02, -3.792583691577223e-02, -2.442185229756283e-02, -1.925404451485950e-02, -1.388410227719867e-02, -7.210064768938013e-03, -2.585177868256875e-03, -4.734312872300584e-04, -2.668887405828609e-05]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


